window.__votdWeek && window.__votdWeek({"week":"2028-05-01","reading":"Mosiah 7–10","days":[{"d":"2028-05-01","ref":"Mosiah 7:29","b":"Mosiah","c":7,"v":29,"he":"כִּי הִנֵּה כֹּה־אָמַר יְהוָה לֹא־אֶעֱזֹר אֶת־עַמִּי בְּיוֹם פִּשְׁעָם כִּי־אִם אֶגְדֹּר אֶת־דַּרְכֵיהֶם לְבִלְתִּי יַצְלִיחוּ וּמַעַלְלֵיהֶם יִהְיוּ לָהֶם לְמִכְשׁוֹל׃","en":"For behold, the Lord hath said: I will not succor my people in the day of their transgression; but I will hedge up their ways that they prosper not; and their doings shall be as a stumbling block before them."},{"d":"2028-05-02","ref":"Mosiah 7:31","b":"Mosiah","c":7,"v":31,"he":"וְעוֹד יֹאמַר אִם־יִזְרַע עַמִּי טֻמְאָה יִקְצְרוּ רוּחַ קָדִים הַמֵּבִיא שֶׁבֶר פִּתְאֹם׃","en":"And again he saith: If my people shall sow filthiness they shall reap the east wind, which bringeth immediate destruction."},{"d":"2028-05-03","ref":"Mosiah 8:9","b":"Mosiah","c":8,"v":9,"he":"וּלְעֵדוּת כִּי אֱמֶת דִּבְרֵיהֶם הֵבִיאוּ עֶשְׂרִים וְאַרְבָּעָה לוּחוֹת מְלֵאִים פִּתּוּחִים וְהֵם זָהָב טָהוֹר׃","en":"And for a testimony that the things that they had said are true they have brought twenty-four plates which are filled with engravings, and they are of pure gold."},{"d":"2028-05-04","ref":"Mosiah 8:10","b":"Mosiah","c":8,"v":10,"he":"וְהִנֵּה גַם הֵבִיאוּ שִׁרְיוֹנִים גְּדוֹלִים וְהֵם נְחֹשֶׁת קָלָל וּנְחוּשָׁה וּשְׁלֵמִים הֵם׃","en":"And behold, also, they have brought breastplates, which are large, and they are of brass and of copper, and are perfectly sound."},{"d":"2028-05-05","ref":"Mosiah 9:10","b":"Mosiah","c":9,"v":10,"he":"וְעַתָּה בְּעׇרְמַת לָמָן הַמֶּלֶךְ וּבְנִכְלָיו לְהָבִיא אֶת־עַמִּי לְעַבְדוּת נָתַן לָנוּ אֶת־הָאָרֶץ לְרִשְׁתָּהּ׃","en":"Now it was the cunning and the craftiness of king Laman, to bring my people into bondage, that he yielded up the land that we might possess it."},{"d":"2028-05-06","ref":"Mosiah 10:6","b":"Mosiah","c":10,"v":6,"he":"וַיָּמׇת לָמָן הַמֶּלֶךְ וַיִּמְלֹךְ בְּנוֹ תַּחְתָּיו וַיָּחֶל לְהָסִית אֶת־עַמּוֹ לִמְרֹד בְּעַמִּי עַל־כֵּן הֵחֵלּוּ לְהִתְכּוֹנֵן לַמִּלְחָמָה וְלַעֲלוֹת לְהִלָּחֵם בְּעַמִּי׃","en":"And it came to pass that king Laman died, and his son began to reign in his stead. And he began to stir his people up in rebellion against my people; therefore they began to prepare for war, and to come up to battle against my people."},{"d":"2028-05-07","ref":"Mosiah 10:20","b":"Mosiah","c":10,"v":20,"he":"וַנְּגָרְשֵׁם שֵׁנִית מֵאַרְצֵנוּ וַנַּכֵּם מַכָּה גְדוֹלָה עַד־אֲשֶׁר לֹא סָפַרְנוּם׃","en":"And it came to pass that we did drive them again out of our land; and we slew them with a great slaughter, even so many that we did not number them."}]});
